def create_roles_and_navigation(apps, schema_editor):
    AccessRole = apps.get_model('store', 'AccessRole')
    UserRole = apps.get_model('store', 'UserRole')
    NavigationItem = apps.get_model('store', 'NavigationItem')
    Craftswoman = apps.get_model('store', 'Craftswoman')
    User = apps.get_model('auth', 'User')

    role_data = (
        ('superadmin', 'Superadministrador', 'Control total de usuarios, permisos, recursos y vistas.', 1),
        ('admin', 'Administrador', 'Gestiona los recursos autorizados de la tienda.', 2),
        ('craftswoman', 'Tejedora', 'Gestiona su taller, pedidos y diseños asignados.', 3),
        ('customer', 'Usuario o cliente', 'Consulta, compra y administra su propia cuenta.', 4),
    )
    roles = {}
    for code, name, description, priority in role_data:
        role, _ = AccessRole.objects.update_or_create(
            code=code,
            defaults={'name': name, 'description': description, 'priority': priority},
        )
        roles[code] = role

    craftswoman_users = set(Craftswoman.objects.exclude(user_id=None).values_list('user_id', flat=True))
    for user in User.objects.all():
        if user.is_superuser:
            code = 'superadmin'
        elif user.is_staff:
            code = 'admin'
        elif user.id in craftswoman_users:
            code = 'craftswoman'
        else:
            code = 'customer'
        UserRole.objects.update_or_create(user_id=user.id, defaults={'role': roles[code]})

    views = (
        ('Catálogo', 'store:catalog', 'catalogo', 'Colección disponible para explorar.', 10, ('superadmin', 'admin', 'craftswoman', 'customer')),
        ('Administración', 'admin:index', '', 'Panel de control de la tienda.', 20, ('superadmin', 'admin')),
        ('Mi taller', 'store:craftswoman_dashboard', '', 'Pedidos y diseños asignados a la tejedora.', 30, ('craftswoman',)),
        ('Crear manta', 'store:custom_designer', '', 'Diseñador de manta personalizada.', 30, ('customer',)),
        ('Mi cuenta', 'store:customer_dashboard', '', 'Pedidos y datos del cliente.', 40, ('customer',)),
        ('Carrito', 'store:cart', '', 'Productos listos para solicitar.', 50, ('customer',)),
    )
    for label, route_name, anchor, description, order, role_codes in views:
        item, _ = NavigationItem.objects.update_or_create(
            route_name=route_name,
            anchor=anchor,
            defaults={'label': label, 'description': description, 'order': order, 'active': True},
        )
        item.roles.set([roles[code] for code in role_codes])


def remove_seeded_navigation(apps, schema_editor):
    NavigationItem = apps.get_model('store', 'NavigationItem')
    NavigationItem.objects.filter(route_name__in=(
        'store:catalog', 'admin:index', 'store:craftswoman_dashboard',
        'store:custom_designer', 'store:customer_dashboard', 'store:cart', 'store:logout',
    )).delete()


